import AVFoundation
import os

/// Native port of the core Earth MIDI layers (js/audio.js) for platforms without WebKit (Apple TV).
/// Oscillators, filters and noise rendered live in one AVAudioSourceNode. No samples, nothing generated by a model.
/// Layers: quakes (FM bell), solar wind pad, ocean surf, X-ray shimmer, jet stream wind, tides drone, planet chord, flare bells.
final class NativeSynth {
    let engine = AVAudioEngine()
    private var source: AVAudioSourceNode!
    private let reverb = AVAudioUnitReverb()
    private let limiter: AVAudioUnitEffect
    let dsp: SynthDSP

    init() {
        let out = engine.outputNode.outputFormat(forBus: 0)
        let sr = out.sampleRate > 0 ? out.sampleRate : 48000
        dsp = SynthDSP(sampleRate: sr)
        let desc = AudioComponentDescription(componentType: kAudioUnitType_Effect, componentSubType: kAudioUnitSubType_PeakLimiter,
                                             componentManufacturer: kAudioUnitManufacturer_Apple, componentFlags: 0, componentFlagsMask: 0)
        limiter = AVAudioUnitEffect(audioComponentDescription: desc)
        let fmt = AVAudioFormat(standardFormatWithSampleRate: sr, channels: 2)!
        let dsp = self.dsp
        source = AVAudioSourceNode(format: fmt) { _, _, frames, abl -> OSStatus in
            let buf = UnsafeMutableAudioBufferListPointer(abl)
            guard buf.count >= 2, let l = buf[0].mData?.assumingMemoryBound(to: Float.self),
                  let r = buf[1].mData?.assumingMemoryBound(to: Float.self) else { return noErr }
            dsp.render(l, r, Int(frames))
            return noErr
        }
        reverb.loadFactoryPreset(.largeHall2)
        reverb.wetDryMix = 32
        engine.attach(source); engine.attach(reverb); engine.attach(limiter)
        engine.connect(source, to: reverb, format: fmt)
        engine.connect(reverb, to: limiter, format: fmt)
        engine.connect(limiter, to: engine.mainMixerNode, format: fmt)
        engine.mainMixerNode.outputVolume = 0.9
    }

    func start() throws {
        #if os(iOS) || os(tvOS)
        try AVAudioSession.sharedInstance().setCategory(.playback, mode: .default, options: [])
        try AVAudioSession.sharedInstance().setActive(true)
        #endif
        if !engine.isRunning { try engine.start() }
        dsp.setMaster(1)
    }
    func stop() {
        dsp.setMaster(0)
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.6) { [weak self] in
            guard let self, self.dsp.masterTarget == 0 else { return }
            self.engine.pause()
        }
    }
    /// Moon illumination 0…1 → reverb amount (site: 0.38…0.85 send)
    func setRoom(moon: Double) { reverb.wetDryMix = Float(mapv(moon, 0, 1, 24, 46)) }
}

// MARK: - DSP

/// Parameters the control loop sets; the audio thread glides toward them (like setTargetAtTime).
struct SynthTargets {
    var padCut = 800.0, padQ = 2.0, padLfoRate = 0.07, padGain = 0.0
    var padFreqs = [Double](repeating: 110, count: 4)
    var padVoiceGain = [Double](repeating: 0.05, count: 4)
    var surfGain = 0.0, surfRate = 0.1, surfBP = 700.0
    var shimGain = 0.0, shimBP = 4000.0
    var windGain = 0.0, windBP1 = 600.0, windBP2 = 1100.0, windLfo = 0.09
    var tideGain = 0.0, tideDetune = 0.0
    var choirGain = 0.0
    var choirFreqs = [Double](repeating: 220, count: 10)
    var mute = Set<Character>()
}

private struct Smooth {
    var v: Double, target: Double, tau: Double
    init(_ v: Double, tau: Double) { self.v = v; target = v; self.tau = tau }
    @inline(__always) mutating func step(_ k: Double) -> Double { v += (target - v) * k; return v }
}

/// RBJ biquad (Web Audio BiquadFilterNode shapes)
private struct Biquad {
    enum Kind { case lp, hp, bp }
    var kind: Kind
    var b0 = 1.0, b1 = 0.0, b2 = 0.0, a1 = 0.0, a2 = 0.0
    var x1 = 0.0, x2 = 0.0, y1 = 0.0, y2 = 0.0
    init(_ k: Kind) { kind = k }
    mutating func set(_ f: Double, _ q: Double, _ sr: Double) {
        let w = 2 * Double.pi * clamp(f, 10, sr * 0.45) / sr, cw = cos(w), sw = sin(w), alpha = sw / (2 * max(0.0001, q))
        let a0 = 1 + alpha
        switch kind {
        case .lp: b0 = (1 - cw) / 2; b1 = 1 - cw; b2 = (1 - cw) / 2
        case .hp: b0 = (1 + cw) / 2; b1 = -(1 + cw); b2 = (1 + cw) / 2
        case .bp: b0 = alpha; b1 = 0; b2 = -alpha
        }
        a1 = -2 * cw; a2 = 1 - alpha
        b0 /= a0; b1 /= a0; b2 /= a0; a1 /= a0; a2 /= a0
    }
    @inline(__always) mutating func run(_ x: Double) -> Double {
        let y = b0 * x + b1 * x1 + b2 * x2 - a1 * y1 - a2 * y2
        x2 = x1; x1 = x; y2 = y1; y1 = y
        return y
    }
}

private struct Pink {
    var b0 = 0.0, b1 = 0.0, b2 = 0.0, seed: UInt32
    init(_ s: UInt32) { seed = s }
    @inline(__always) mutating func white() -> Double { seed = seed &* 1664525 &+ 1013904223; return Double(seed) / 2147483648.0 - 1 }
    @inline(__always) mutating func next() -> Double {
        let w = white()
        b0 = 0.99765 * b0 + w * 0.099; b1 = 0.963 * b1 + w * 0.2965; b2 = 0.57 * b2 + w * 1.0526
        return (b0 + b1 + b2 + w * 0.1848) * 0.18
    }
}

@inline(__always) private func polyBlep(_ t: Double, _ dt: Double) -> Double {
    if t < dt { let x = t / dt; return x + x - x * x - 1 }
    if t > 1 - dt { let x = (t - 1) / dt; return x * x + x + x + 1 }
    return 0
}
@inline(__always) private func saw(_ ph: Double, _ dt: Double) -> Double { 2 * ph - 1 - polyBlep(ph, dt) }
@inline(__always) private func panLR(_ p: Double) -> (Double, Double) { let a = (clamp(p, -1, 1) + 1) * .pi / 4; return (cos(a), sin(a)) }

/// One struck voice: FM quake bell, flare bell or sub hit
private struct Voice {
    var on = false
    var kind = 0 // 0 FM bell, 1 triangle bell, 2 sub sweep, 3 rumble
    var t = 0.0, delay = 0.0, dur = 1.0
    var f = 440.0, ratio = 2.0, idx0 = 1.0, idxDur = 1.0, p2 = 4.0
    var amp = 0.1, pl = 0.7, pr = 0.7, wet = 0.4
    var phC = 0.0, phM = 0.0, ph2 = 0.0
    var lp = Biquad(.lp)
    var f0 = 0.0, f1 = 0.0
}

final class SynthDSP {
    let sr: Double
    private var lock = os_unfair_lock()
    private var pending = SynthTargets()
    private var pendingVoices: [Voice] = []
    private var tg = SynthTargets()
    private(set) var masterTarget = 0.0
    private var master = Smooth(0, tau: 0.3)

    // pad
    private var padPh = [Double](repeating: 0, count: 8)
    private var padF = (0..<4).map { _ in Smooth(110, tau: 0.9) }
    private var padVG = (0..<4).map { _ in Smooth(0.05, tau: 1) }
    private var padDet: [Double] = ([-7, 7, -7, 7, -7, 7, -7, 7] as [Double]).enumerated().map { i, d in d + Double((i * 37) % 5) - 2 }
    private var padCut = Smooth(800, tau: 1.5), padQ = Smooth(2, tau: 2), padG = Smooth(0, tau: 1), padLfoR = Smooth(0.07, tau: 2)
    private var padLP = Biquad(.lp), padLP2 = Biquad(.lp), padHP = Biquad(.hp), padHP2 = Biquad(.hp), padLfo = 0.0
    // surf
    private var surfN = Pink(7), surfBP = Biquad(.bp), surfLP = Biquad(.lp)
    private var surfG = Smooth(0, tau: 1), surfRate = Smooth(0.1, tau: 1), surfF = Smooth(700, tau: 2), surfPh = 0.0, surfPanPh = 0.0
    // shimmer
    private var shimPh = [0.0, 0, 0, 0], shimLfo = [0.0, 0, 0, 0], shimBPL = Biquad(.bp), shimBPR = Biquad(.bp)
    private var shimG = Smooth(0, tau: 1.2), shimF = Smooth(4000, tau: 2)
    private let shimFreq = [74, 81, 86, 93].map { Music.mtof($0) }, shimPan = [-0.7, 0.7, -0.3, 0.3]
    // wind
    private var windN = Pink(11), windBP1 = Biquad(.bp), windBP2 = Biquad(.bp), windLfoPh = 0.0, windPanPh = 0.0
    private var windG = Smooth(0, tau: 1.5), windF1 = Smooth(600, tau: 2), windF2 = Smooth(1100, tau: 2), windLR = Smooth(0.09, tau: 2)
    // tide
    private var tidePh = [0.0, 0.0], tideLP = Biquad(.lp), tideG = Smooth(0, tau: 1), tideDet = Smooth(0, tau: 1)
    // choir
    private var choirPh = [Double](repeating: 0, count: 10), choirF = (0..<10).map { _ in Smooth(220, tau: 1.2) }
    private var choirVib = 0.0, choirG = Smooth(0, tau: 1.5)
    private var formL1 = Biquad(.bp), formL2 = Biquad(.bp), formR1 = Biquad(.bp), formR2 = Biquad(.bp)
    private let choirPan: [Double] = EarthData.cities.map { clamp($0.lon / 180, -1, 1) * 0.8 }
    // struck voices + ping-pong delay for quakes
    private var voices = [Voice](repeating: Voice(), count: 32)
    private var dl: [Float], dr: [Float], dIdx = 0, dLen: Int, dlLP = Biquad(.lp)
    private var rumble = Pink(23)
    private var ctr = 0

    init(sampleRate: Double) {
        sr = sampleRate
        dLen = Int(sampleRate * 0.375)
        dl = [Float](repeating: 0, count: dLen); dr = [Float](repeating: 0, count: dLen)
        padHP.set(70, 0.707, sr); padHP2.set(70, 0.707, sr)
        surfLP.set(2500, 0.707, sr)
        tideLP.set(420, 0.5, sr)
        formL1.set(720, 3, sr); formR1.set(720, 3, sr); formL2.set(1150, 4, sr); formR2.set(1150, 4, sr)
        dlLP.set(3200, 0.707, sr)
        shimBPL.set(4000, 0.7, sr); shimBPR.set(4000, 0.7, sr)
    }

    // MARK: control side (main thread)
    func update(_ t: SynthTargets) { os_unfair_lock_lock(&lock); pending = t; os_unfair_lock_unlock(&lock) }
    func setMaster(_ v: Double) { masterTarget = v }

    /// js quakeVoice(): FM bell, depth picks the modulator ratio, magnitude sets brightness and length; M4.5+ adds a sub hit
    func quake(note: Int, vel: Int, mag: Double, depth: Double, pan: Double) {
        let f = Music.mtof(note), velN = Double(vel) / 127
        var v = Voice(); v.on = true; v.kind = 0; v.f = f
        v.ratio = depth > 70 ? 1.4 : 2; v.idx0 = mapv(mag, 1, 7, 1.5, 6); v.p2 = 4.007
        v.dur = 1.2 + mag * 0.9; v.idxDur = v.dur * 0.6
        v.amp = pow(velN, 1.6) * 0.55
        (v.pl, v.pr) = panLR(pan); v.wet = 1
        v.lp.set(mapv(Double(vel), 20, 127, 1800, 9000), 0.707, sr)
        var list = [v]
        if mag >= 4.5 {
            var s = Voice(); s.on = true; s.kind = 2; s.f0 = Music.mtof(Music.root - 12) * 2.2; s.f1 = Music.mtof(Music.root - 12)
            s.amp = mapv(mag, 4.5, 8, 0.24, 0.45); s.dur = 1.5 + mag * 0.4; (s.pl, s.pr) = (0.7, 0.7); list.append(s)
            var n = Voice(); n.on = true; n.kind = 3; n.amp = mapv(mag, 4.5, 8, 0.35, 0.75); n.dur = mag * 0.9; (n.pl, n.pr) = (0.7, 0.7)
            n.lp.set(140, 0.707, sr); list.append(n)
        }
        push(list)
    }
    /// js flareBell(): four bells a fifth/octave apart, root + 24
    func flare() {
        push([0, 7, 12, 19].enumerated().map { i, d in
            var v = Voice(); v.on = true; v.kind = 1; v.f = Music.mtof(Music.root + 24 + d); v.delay = Double(i) * 0.12
            v.amp = 0.08; v.dur = 5; (v.pl, v.pr) = panLR([-0.4, 0.4, -0.15, 0.15][i]); return v
        })
    }
    private func push(_ v: [Voice]) { os_unfair_lock_lock(&lock); pendingVoices.append(contentsOf: v); os_unfair_lock_unlock(&lock) }

    // MARK: audio thread
    func render(_ L: UnsafeMutablePointer<Float>, _ R: UnsafeMutablePointer<Float>, _ n: Int) {
        if os_unfair_lock_trylock(&lock) {
            tg = pending
            if !pendingVoices.isEmpty {
                for nv in pendingVoices {
                    if let i = voices.firstIndex(where: { !$0.on }) { voices[i] = nv }
                    else if let i = voices.indices.max(by: { voices[$0].t < voices[$1].t }) { voices[i] = nv } // steal the oldest
                }
                pendingVoices.removeAll(keepingCapacity: true)
            }
            os_unfair_lock_unlock(&lock)
        }
        let dt = 1 / sr
        let k = { (tau: Double) in 1 - exp(-dt / tau) }
        let kPad = k(0.9), kPadV = k(1), kCut = k(1.5), kQ = k(2), kG1 = k(1), kG15 = k(1.5), kG12 = k(1.2), kF2 = k(2), kMaster = k(0.3)
        for i in 0..<4 { padF[i].target = tg.padFreqs[i]; padVG[i].target = tg.padVoiceGain[i] }
        padCut.target = tg.padCut; padQ.target = tg.padQ; padG.target = tg.mute.contains("s") ? 0 : tg.padGain; padLfoR.target = tg.padLfoRate
        surfG.target = tg.mute.contains("o") ? 0 : tg.surfGain; surfRate.target = tg.surfRate; surfF.target = tg.surfBP
        shimG.target = tg.mute.contains("x") ? 0 : tg.shimGain; shimF.target = tg.shimBP
        windG.target = tg.mute.contains("w") ? 0 : tg.windGain; windF1.target = tg.windBP1; windF2.target = tg.windBP2; windLR.target = tg.windLfo
        tideG.target = tg.mute.contains("t") ? 0 : tg.tideGain; tideDet.target = tg.tideDetune
        choirG.target = tg.mute.contains("c") ? 0 : tg.choirGain
        for i in 0..<10 { choirF[i].target = tg.choirFreqs[i] }
        master.target = masterTarget
        let qMuted = tg.mute.contains("q")

        for s in 0..<n {
            // control-rate filter updates every 32 samples
            if ctr & 31 == 0 {
                let lfo = sin(padLfo * 2 * .pi) * 250
                padLP.set(padCut.v + lfo, padQ.v, sr); padLP2.set(padCut.v + lfo, padQ.v, sr)
                surfBP.set(surfF.v, 0.6, sr)
                let wl = sin(windLfoPh * 2 * .pi) * 220
                windBP1.set(windF1.v + wl, 5, sr); windBP2.set(windF2.v + wl, 9, sr)
                shimBPL.set(shimF.v, 0.7, sr); shimBPR.set(shimF.v, 0.7, sr)
            }
            ctr &+= 1
            var l = 0.0, r = 0.0

            // solar wind pad: 4 chord tones × 2 detuned saws
            let pg = padG.step(kG1)
            if pg > 0.0005 {
                var pl = 0.0, pr = 0.0
                for v in 0..<4 {
                    let f = padF[v].step(kPad), vg = padVG[v].step(kPadV)
                    for d in 0..<2 {
                        let j = v * 2 + d, fr = f * pow(2, padDet[j] / 1200), inc = fr * dt
                        padPh[j] += inc; if padPh[j] >= 1 { padPh[j] -= 1 }
                        let x = saw(padPh[j], inc) * vg
                        if d == 0 { pl += x * 0.8; pr += x * 0.35 } else { pl += x * 0.35; pr += x * 0.8 }
                    }
                }
                l += padHP.run(padLP.run(pl)) * pg; r += padHP2.run(padLP2.run(pr)) * pg
            } else { for v in 0..<4 { _ = padF[v].step(kPad); _ = padVG[v].step(kPadV) } }
            _ = padCut.step(kCut); _ = padQ.step(kQ)
            padLfo += padLfoR.step(kQ) * dt; if padLfo >= 1 { padLfo -= 1 }

            // ocean surf: noise breathing at the real swell period
            let sg = surfG.step(kG1); _ = surfF.step(kF2)
            surfPh += surfRate.step(kG1) * dt; if surfPh >= 1 { surfPh -= 1 }
            surfPanPh += 0.031 * dt; if surfPanPh >= 1 { surfPanPh -= 1 }
            if sg > 0.0005 {
                let x = surfLP.run(surfBP.run(surfN.next())) * (0.5 + 0.5 * sin(surfPh * 2 * .pi)) * sg * 2.2
                let (a, b) = panLR(0.6 * sin(surfPanPh * 2 * .pi)); l += x * a; r += x * b
            }

            // X-ray shimmer: four high sines fading in and out
            let xg = shimG.step(kG12); _ = shimF.step(kF2)
            if xg > 0.0005 {
                var xl = 0.0, xr = 0.0
                for i in 0..<4 {
                    shimPh[i] += shimFreq[i] * dt; if shimPh[i] >= 1 { shimPh[i] -= 1 }
                    shimLfo[i] += (0.13 + Double(i) * 0.07) * dt; if shimLfo[i] >= 1 { shimLfo[i] -= 1 }
                    let x = sin(shimPh[i] * 2 * .pi) * 0.05 * sin(shimLfo[i] * 2 * .pi)
                    let (a, b) = panLR(shimPan[i]); xl += x * a; xr += x * b
                }
                l += shimBPL.run(xl) * xg * 3; r += shimBPR.run(xr) * xg * 3
            }

            // jet stream: resonant wind
            let wg = windG.step(kG15); _ = windF1.step(kF2); _ = windF2.step(kF2)
            windLfoPh += windLR.step(kF2) * dt; if windLfoPh >= 1 { windLfoPh -= 1 }
            windPanPh += 0.05 * dt; if windPanPh >= 1 { windPanPh -= 1 }
            if wg > 0.0005 {
                let nz = windN.next(), x = (windBP1.run(nz) + windBP2.run(nz)) * wg * 1.5
                let (a, b) = panLR(0.8 * sin(windPanPh * 2 * .pi)); l += x * a; r += x * b
            }

            // tides: sub drone bent by the measured water level
            let tgn = tideG.step(kG1), det = pow(2, tideDet.step(kG1) / 1200)
            tidePh[0] += Music.mtof(Music.root - 12) * det * dt; if tidePh[0] >= 1 { tidePh[0] -= 1 }
            tidePh[1] += Music.mtof(Music.root) * det * dt; if tidePh[1] >= 1 { tidePh[1] -= 1 }
            if tgn > 0.0005 {
                let x = tideLP.run(sin(tidePh[0] * 2 * .pi) + 0.35 * sin(tidePh[1] * 2 * .pi)) * tgn
                l += x; r += x
            }

            // planet chord: a voice per city, pitch = temperature, through two vowel formants
            let cg = choirG.step(kG15)
            choirVib += 4.6 * dt; if choirVib >= 1 { choirVib -= 1 }
            let vib = pow(2, 4 * sin(choirVib * 2 * .pi) / 1200)
            if cg > 0.0005 {
                var cl = 0.0, cr = 0.0
                for i in 0..<10 {
                    let inc = choirF[i].step(kG12) * vib * dt
                    choirPh[i] += inc; if choirPh[i] >= 1 { choirPh[i] -= 1 }
                    let x = saw(choirPh[i], inc) * 0.022
                    let (a, b) = panLR(choirPan[i]); cl += x * a; cr += x * b
                }
                l += (formL1.run(cl) + formL2.run(cl) + cl * 0.35) * cg
                r += (formR1.run(cr) + formR2.run(cr) + cr * 0.35) * cg
            } else { for i in 0..<10 { _ = choirF[i].step(kG12) } }

            // struck voices
            var ql = 0.0, qr = 0.0
            for i in 0..<voices.count where voices[i].on {
                voices[i].t += dt
                let v = voices[i], t = v.t - v.delay
                if t < 0 { continue }
                if t > v.dur + 0.1 { voices[i].on = false; continue }
                var x = 0.0
                switch v.kind {
                case 0:
                    let env = t < 0.005 ? v.amp * t / 0.005 : v.amp * pow(0.0005 / v.amp, (t - 0.005) / max(0.01, v.dur - 0.005))
                    let idx = v.f * v.idx0 * pow(0.02 / v.idx0, min(1, t / v.idxDur))
                    voices[i].phM += v.f * v.ratio * dt; if voices[i].phM >= 1 { voices[i].phM -= 1 }
                    let fm = idx * sin(voices[i].phM * 2 * .pi)
                    voices[i].phC += (v.f + fm) * dt; voices[i].phC -= voices[i].phC.rounded(.down)
                    voices[i].ph2 += v.f * v.p2 * dt; if voices[i].ph2 >= 1 { voices[i].ph2 -= 1 }
                    let partial = v.amp * 0.12 * pow(0.0001 / (v.amp * 0.12), min(1, t / (v.dur * 0.35)))
                    x = voices[i].lp.run(sin(voices[i].phC * 2 * .pi) * env) + sin(voices[i].ph2 * 2 * .pi) * partial
                case 1:
                    let env = t < 0.02 ? v.amp * t / 0.02 : v.amp * pow(0.0003 / v.amp, (t - 0.02) / (v.dur - 0.02))
                    voices[i].phC += v.f * dt; if voices[i].phC >= 1 { voices[i].phC -= 1 }
                    let p = voices[i].phC; x = (p < 0.5 ? 4 * p - 1 : 3 - 4 * p) * env
                case 2:
                    let f = t < 0.35 ? v.f0 * pow(v.f1 / v.f0, t / 0.35) : v.f1
                    let env = t < 0.01 ? v.amp * t / 0.01 : v.amp * pow(0.0005 / v.amp, (t - 0.01) / v.dur)
                    voices[i].phC += f * dt; if voices[i].phC >= 1 { voices[i].phC -= 1 }
                    x = sin(voices[i].phC * 2 * .pi) * env
                default:
                    let env = t < 0.08 ? v.amp * t / 0.08 : v.amp * pow(0.0005 / v.amp, (t - 0.08) / max(0.1, v.dur - 0.08))
                    x = voices[i].lp.run(rumble.white()) * env * 2
                }
                if qMuted && v.kind != 1 { continue }
                ql += x * v.pl; qr += x * v.pr
            }
            // ping-pong delay on the quake bells (0.375 s, 38 % feedback, 3.2 kHz damping)
            let dOutL = Double(dl[dIdx]), dOutR = Double(dr[dIdx])
            let fbIn = dlLP.run(dOutL)
            dl[dIdx] = Float(ql * 0.3 + dOutR * 0.38)
            dr[dIdx] = Float(fbIn)
            dIdx += 1; if dIdx >= dLen { dIdx = 0 }
            l += ql + dOutL; r += qr + dOutR

            // master: headroom trim then a soft saturator, then fade
            let m = master.step(kMaster) * 0.72
            L[s] = Float(tanh(l * m * 1.1) * 0.9)
            R[s] = Float(tanh(r * m * 1.1) * 0.9)
        }
    }
}
